"""g2's ten backs: every figure is one union silhouette (outer pen contour), cloth and hair pushed by the wind, left arm = one ribbon from shoulder to fist."""
import numpy as np, math
from .paint import rgb, smooth
from .ink import Cel, spl, resample
from .kit import outline, hatch as _hatch
from .comp import lerp_keys
A_ = np.asarray
INK = '#191114'


def gust(f, ph=0.):
    f = f - ph; return .20 + .05 * math.sin(f * .25) + float(lerp_keys(f, [(26, 0), (30, .55), (34, 1.0), (40, .62), (52, .52), (60, .68), (72, .50), (90, .58)])) * (1 + .12 * math.sin(f * .55))


def ccw(P):
    x, y = P[:, 0], P[:, 1]; return P if (np.roll(x, -1) * y - x * np.roll(y, -1)).sum() > 0 else P[::-1]


class Back:
    def __init__(s, x, y, k, f, hit, rest, seed=0, tone=1.):
        s.x, s.y, s.k, s.f, s.hit, s.rest, s.seed, s.tone = x, y, k, f, hit, rest, seed, tone; s.g = (f // 2) * 2; s.w = gust(s.g, (x - 200) / 380.); s.ph = seed * 1.3; s.ops = []
        q = f - hit; s.react = float(lerp_keys(q, [(-10, 0), (-6, -.6), (-1, .9), (1, 1.15), (5, .75), (9, .85)])); s.br = 1.6 * math.sin(s.g * .23 + s.ph)
        s.c = Cel(1000, 900, int(x) - 500, int(y) - 800)

    def D(s, P):
        Q = np.zeros((len(P), 2))
        for i, p in enumerate(P):
            w = p[2] if len(p) > 2 else 0.; o = 1 + .30 * math.sin(.55 * s.g - 2.2 * w + s.ph) + .14 * math.sin(1.13 * s.g + 3 * w + s.ph * 2); up = min(1., max(0., -p[1] / 120.)); q = (p[0] + 46 * w * s.w * o, p[1] - 11 * w * s.w * o + 5 * w * math.sin(.8 * s.g + 4 * w + s.ph) - (s.br * .6 + 2.5 * s.react) * up); t = .010 * s.react * up
            Q[i] = (q[0] - q[1] * t, q[1])
        return Q * s.k + [s.x, s.y]

    def col(s, c, m=1.): c = rgb(c) * m * s.tone; return tuple(np.clip(c, 0, 1))
    def poly(s, P, cor=(), n=7): return ccw(spl(s.D(P), True, corners=cor, n=n))
    def comp(s, P, col, cor=(), inner=1.6, n=7, raw=False):
        Q = P if raw else s.poly(P, cor, n); s.ops.append(('fill', ccw(Q), col, inner)); return Q
    def shade(s, P, clip, m=.62, col=None, n=7): s.ops.append(('shade', s.poly(P, (), n), clip, m, col))
    def ln(s, P, w=1.6, al=.85, col=INK, clip=None): s.ops.append(('line', spl(s.D(P), n=8), w, al, col, clip))
    def hat(s, P, ang=1.1, gap=7.5, clip=None, w=1.5, fade=.5, L=None): s.ops.append(('hatch', s.poly(P), ang, gap, w, fade, clip, L))
    def tuft(s, pts, col): return s.comp(pts, col, (len(pts) // 2,), 1.4)

    def rib(s, path, w0, prof, n=10):
        """ribbon polygon round a px path; prof [(t, half width / w0)]  -> (poly, centre fn)"""
        C = resample(spl(A_(path, float), n=n), 2.); T = np.gradient(C, axis=0); T /= np.hypot(*T.T)[:, None] + 1e-6; N = np.c_[-T[:, 1], T[:, 0]]; t = np.linspace(0, 1, len(C)); pt, pw = zip(*prof); h = np.interp(t, pt, pw) * w0 * s.k; kk = np.hanning(7); kk /= kk.sum(); h = np.convolve(np.pad(h, 3, mode='edge'), kk, 'valid'); A, B = C + N * h[:, None], C - N * h[:, None]
        return np.vstack([A, B[::-1]]), A, B, C, T, N

    LIMB = [(0, .50), (.2, .50), (.48, .40), (.62, .42), (.86, .30), (.93, .36), (1, .22)]
    def limb(s, P, w, col, inner=1.6, sleeve=None, scol=None, prof=None):
        R = s.rib(s.D(P), w, prof or s.LIMB); s.comp(R[0], col, inner=inner, raw=True)
        if sleeve: i = int(len(R[1]) * sleeve); s.ops.append(('slice', np.vstack([R[1][:i], R[2][:i][::-1]]), scol, R[0]))
        return R

    ARM = [(0, .50), (.10, .54), (.26, .54), (.45, .43), (.56, .50), (.64, .50), (.80, .34), (.845, .34), (.885, .50), (.95, .52), (.985, .40), (1., .20)]
    def arm(s, S, L, w, skin, sleeve=None, sl=.5, prof=None, band=(.57, .79), fist=None, hoof=None, out=0.):
        """left arm: one shape.  rest = (a1, a2) degrees; swings out and up to land on s.hit"""
        w, L = w * 1.16, L * 1.07; a1, a2 = s.rest; q = s.f - s.hit; u1, u2 = -266. + out, -269. + out
        A1 = float(lerp_keys(q, [(-11, a1), (-6, a1 + 11), (-3, a1 - 74), (-1, u1 + 26), (0, u1 - 3), (2, u1 - 5), (5, u1 + 2), (9, u1)], lambda t: t)); A2 = float(lerp_keys(q, [(-11, a2), (-6, a2 + 9), (-3, a2 - 30), (-1, u2 + 62), (0, u2 + 14), (2, u2 - 17), (5, u2 + 5), (9, u2)], lambda t: t)); d = lambda a: A_([math.cos(math.radians(a)), -math.sin(math.radians(a))]); S = A_(S, float) + [-2 * max(0, s.react), 5 * max(0, -s.react) - 9 * max(0, s.react)]
        st = float(lerp_keys(q, [(-6, 1), (-1, 1.02), (0, 1.07), (2, 1.04), (6, 1.)])); E = S + d(A1) * L * .46 * st; W_ = E + d(A2) * L * .38 * st; F = W_ + d(A2 - 2) * L * .17; pts = [tuple(S), tuple(S + (E - S) * .5), tuple(E), tuple(E + (W_ - E) * .5), tuple(W_), tuple(F)]; R = s.rib(s.D(pts), w, prof or s.ARM, 8); Q, A, B, C, T, N = R; m = len(A); s.armR = R
        up_ = s.react > .25; first = [o[1] for o in s.ops if o[0] == 'fill']; s.comp(Q, skin, inner=0 if up_ else 1.7, raw=True); sl_ = lambda t0, t1: np.vstack([A[int(t0 * (m - 1)):int(t1 * (m - 1)) + 1], B[int(t0 * (m - 1)):int(t1 * (m - 1)) + 1][::-1]])
        if fist is not None: s.ops.append(('slice', sl_(.84, 1.), fist, Q))
        if sleeve: s.ops.append(('slice', sl_(0, sl), sleeve, Q)); i = int(sl * (m - 1)); s.ops.append(('line', np.vstack([A[i], C[i] + T[i] * 3 * s.k, B[i]]), 1.6, .9, INK, Q))
        if up_: e = np.linspace(0, 6.283, 18)[:-1]; pc = ccw(s.D([tuple(S)]) + np.c_[np.cos(e), np.sin(e)] * w * .60 * s.k); s.ops.append(('slice', pc, sleeve or skin, first + [Q]))
        # bandage, wraps, X
        b = sl_(*band); s.ops.append(('slice', b, '#e6dac4', Q)); i0, i1 = int(band[0] * (m - 1)), int(band[1] * (m - 1)); at = lambda t, q_: C[int((band[0] + (band[1] - band[0]) * t) * (m - 1))] + (A - C)[int((band[0] + (band[1] - band[0]) * t) * (m - 1))] * q_
        for i in (i0, i1): s.ops.append(('line', np.vstack([A[i], B[i]]), 1.8, .95, INK, Q))
        for t in (.22, .5, .78): s.ops.append(('line', np.vstack([at(t, 1.), at(min(1, t + .06), 0.), at(t - .04, -1.)]), 1.0, .4, INK, Q))
        xw = max(3.0, w * s.k * .13); s.ops.append(('line', np.vstack([at(.10, .66), at(.5, 0), at(.90, -.66)]), xw, 1., '#100b0d', Q)); s.ops.append(('line', np.vstack([at(.10, -.66), at(.5, 0), at(.90, .66)]), xw, 1., '#100b0d', Q))
        if hoof is None:
            tb = C[int(.90 * (m - 1))]; sd = (A - C)[int(.885 * (m - 1))] * (1 if s.x < 960 else -1); s.ops.append(('line', np.vstack([C[int(.86 * (m - 1))] - sd * 1., tb - sd * .35, tb + T[int(.90 * (m - 1))] * 5 * s.k + sd * .25]), 1.6, .85, INK, Q))
            for q_ in (-.45, 0., .45): s.ops.append(('line', np.vstack([C[int(.90 * (m - 1))] + (A - C)[int(.90 * (m - 1))] * q_, C[int(.97 * (m - 1))] + (A - C)[int(.97 * (m - 1))] * q_]), 1.2, .7, INK, Q))
        else: s.ops.append(('slice', sl_(.86, 1.), hoof, Q))
        # shade down the side away from the sun
        lee = B if s.x > 960 else A; s.ops.append(('shade', np.vstack([lee, (C + (lee - C) * .30)[::-1]]), Q, .68, None)); return R

    def done(s, lw=3.4):
        c = s.c; fills = [o for o in s.ops if o[0] == 'fill']
        for i, o in enumerate(fills): outline(c, o[1], lw * 1.7, INK, seed=s.seed * 37 + i, press=.45, tremor=.25)
        prior = []
        for i, o in enumerate(s.ops):
            if o[0] == 'fill':
                c.fill(o[1], s.col(o[2]))
                if o[3] and prior: c.clip(prior); outline(c, o[1], o[3], INK, seed=s.seed * 13 + i, breaks=1); c.unclip()
                prior.append(o[1])
            elif o[0] == 'slice': c.clip(o[3]); c.fill(o[1], s.col(o[2])); c.unclip()
            elif o[0] == 'shade': c.clip(o[2]); c.fill(o[1], s.col(o[4]) if o[4] else '#1a0f16', 1. if o[4] else 1 - o[3]); c.unclip()
            elif o[0] == 'hatch':
                if o[6] is not None: c.clip(o[6])
                _hatch(c, o[1], o[2], o[3] * s.k, o[4], INK, seed=s.seed + i, fade=o[5], alpha=.75, length=o[7])
                if o[6] is not None: c.unclip()
            elif o[0] == 'line':
                if o[5] is not None: c.clip(o[5])
                c.line(o[1], o[2], o[4], taper=(.12, .4), seed=s.seed * 11 + i, alpha=o[3], press=.35)
                if o[5] is not None: c.unclip()
        return c


# ================================================================== the ten (local px, y up is negative, feet at 0; third number = wind weight)
def zoro(b):
    co, sk, hr = '#37443a', '#8f6749', '#55684a'
    for k, (cc, dy) in enumerate((('#2a2530', 10), ('#5e3427', 4), ('#d4cab6', -3))): b.limb([(44, -196 + dy), (92, -138 + dy), (146, -92 + dy * 1.6)], 13, cc, prof=[(0, .45), (.9, .42), (1, .25)], inner=1.4); b.limb([(44, -196 + dy), (22, -214 + dy)], 12, ('#e0d6c2', '#6b3328', '#241f28')[2 - k], prof=[(0, .42), (1, .40)], inner=1.2)
    B = b.comp([(-13, -308), (-32, -299), (-58, -292), (-70, -268), (-57, -236), (-47, -205), (-42, -182), (-54, -122, .12), (-66, -62, .28), (-74, -12, .42), (-42, -2, .5), (-10, -14, .62), (26, 0, .8), (66, -16, 1.05), (108, -30, 1.5), (90, -84, .95), (68, -142, .45), (58, -186, .12), (54, -214), (61, -244), (70, -266), (60, -283), (35, -294), (16, -304)], co, (9, 11, 14), 0)
    b.shade([(-80, -10), (-74, -300), (-20, -300), (-4, -250), (-18, -200), (4, -140, .2), (-14, -60, .4), (0, 0, .6)], B); b.comp([(-50, -206), (0, -200), (56, -212), (56, -190), (0, -178), (-46, -186)], '#742f29', (0, 2, 3, 5), 1.6)
    b.comp([(-14, -316), (14, -314), (15, -300), (-13, -302)], sk, (), 1.2); b.comp([(-30, -298), (-13, -306), (14, -304), (33, -294), (18, -288), (-16, -290)], '#2e3930', (0, 3), 1.5)
    b.hat([(-8, -290), (8, -250), (-6, -214), (-30, -214), (-30, -290)], 1.0, 7, B); b.hat([(-4, -170), (6, -80, .4), (-10, -30, .5), (-30, -30, .4), (-30, -170)], 1.25, 8, B); b.ln([(0, -288), (4, -250), (0, -208)], 1.8, clip=B); b.ln([(46, -196), (10, -176), (-26, -168)], 1.6, clip=B); b.ln([(50, -186), (22, -146, .2), (4, -96, .4)], 1.8, clip=B); b.ln([(42, -182), (48, -120, .3), (56, -60, .7)], 1.8, clip=B); b.ln([(-34, -176), (-40, -110, .1), (-44, -50, .3)], 1.5, clip=B); b.ln([(-60, -262), (-40, -246), (-22, -244)], 1.4, clip=B); b.ln([(62, -258), (40, -240), (24, -240)], 1.4, clip=B)
    b.limb([(60, -276), (84, -246), (92, -222), (74, -198), (46, -190)], 42, co); R = b.arm((-58, -276), 188, 42, sk, co, .46)
    A, B2, C, T = R[1], R[2], R[3], R[4]; m = len(A); i, j = int(.24 * m), int(.33 * m); b.ops.append(('slice', np.vstack([A[i:j], B2[i:j][::-1]]), '#17161a', R[0])); p = C[j]; b.ops.append(('fill', np.vstack([p + [2, -4], p + [22 + 16 * b.w, -2], p + [30 + 22 * b.w, 8], p + [10, 6]]), '#17161a', 1.2))
    H = b.comp([(-26, -316), (-31, -338), (-42, -356, .05), (-28, -361), (-33, -383, .05), (-15, -376), (-8, -396, .08), (3, -380), (15, -396, .1), (20, -375), (37, -380, .12), (32, -359), (43, -352, .12), (33, -338), (28, -318), (10, -310), (-12, -311)], hr, (2, 4, 6, 8, 10, 12), 1.6, 5); b.shade([(-50, -310), (-50, -380), (-12, -384), (-4, -345), (-16, -310)], H, .66); b.ln([(-18, -370), (-21, -345), (-14, -320)], 1.3, .6); b.ln([(0, -374), (0, -345)], 1.3, .6); b.ln([(17, -370), (20, -345), (14, -322)], 1.3, .6); b.comp([(-31, -340), (-37, -332), (-33, -320), (-28, -320)], sk, (), 1.2)
    for k in range(3): b.ln([(-34 + k * .8, -322 + 2 * k), (-35 + k + 1.5 * b.w, -311 + 2.5 * k)], 2.2, 1., '#b99a4c')


def sanji(b):
    bk, hr = '#27262d', '#ab9058'
    B = b.comp([(-11, -306), (-28, -299), (-50, -291), (-58, -268), (-47, -236), (-41, -202), (-47, -156), (-46, -98), (-46, -40), (-44, 4), (-12, 4), (-6, -80), (2, -128), (12, -80), (28, 4), (60, 4), (54, -90), (50, -150), (58, -158, .35), (47, -200), (49, -236), (58, -266), (50, -287), (28, -298), (11, -305)], bk, (7, 9, 10, 14, 15, 18), 0)
    b.shade([(-60, 0), (-64, -300), (-18, -300), (-2, -240), (-12, -160), (-20, -90), (-18, 0)], B, .55); b.shade([(0, -120), (12, -60), (24, 4), (14, 4), (2, -90)], B, .55); b.ln([(0, -300), (4, -236), (0, -166)], 1.6, clip=B, col='#0f0d11'); b.ln([(-46, -160), (0, -152), (50, -158)], 1.8, clip=B, col='#0f0d11'); b.ln([(-46, -262), (-28, -248), (-12, -250)], 1.4, clip=B, col='#0f0d11'); b.ln([(48, -258), (30, -246), (14, -250)], 1.4, clip=B, col='#0f0d11'); b.ln([(40, -196), (18, -184), (-8, -186)], 1.4, clip=B, col='#0f0d11')
    b.limb([(50, -278), (76, -240), (80, -220), (54, -192), (42, -180)], 34, bk); b.arm((-50, -277), 182, 35, '#ad8468', bk, .50); b.comp([(-13, -314), (13, -314), (16, -298), (0, -292), (-16, -298)], '#a3944c', (0, 1), 1.3)
    H = b.comp([(-24, -314), (-34, -320), (-35, -344), (-26, -364), (-9, -376), (10, -376), (26, -364), (35, -344), (36, -326, .12), (48, -312, .5), (30, -310, .25), (20, -302, .25), (4, -309, .1), (-10, -304)], hr, (9, 11, 13), 1.6); b.shade([(-50, -300), (-50, -370), (-14, -378), (-4, -340), (-12, -300)], H, .68)
    for q in (-20, -6, 8, 22): b.ln([(q * .5, -374), (q * 1.05, -345), (q * 1.1 + 3, -316, .15)], 1.3, .6)
    for k in range(3): t = b.f * .055 + k; b.ops.append(('line', spl(A_([(30 + 24 * q + (30 + 85 * b.w) * q * q, -322 - 104 * q * (1 - .35 * b.w) + 7 * math.sin(q * 8 - t * 3 + k)) for q in np.linspace(0, 1, 9)]) * b.k + [b.x, b.y], n=6), 6 - k * 1.5, .40, '#efe4cf', None))


def brook(b):
    bk = '#302b35'; bo = '#9c5a36'
    for sg, c in ((-1, '#54434c'), (1, '#604c55')): b.limb([(sg * 14, -120), (sg * 18, -60), (sg * 20, 6)], 24, c, prof=[(0, .5), (1, .42)])
    B = b.comp([(-12, -332), (-36, -322), (-47, -296), (-37, -250), (-34, -204), (-42, -134, .1), (-53, -62, .28), (-56, -14, .42), (-24, -24, .6), (0, -70, .3), (20, -18, .8), (60, -8, 1.1), (98, -24, 1.6), (72, -82, .9), (46, -150, .3), (38, -208), (41, -256), (48, -298), (38, -322), (13, -332)], bk, (7, 9, 12), 0); b.shade([(-60, 0), (-60, -330), (-14, -330), (0, -260), (-10, -170), (-18, -80, .3), (-24, 0, .6)], B, .60); b.ln([(2, -318), (2, -220), (0, -72, .2)], 1.6, clip=B); b.ln([(24, -220), (34, -150, .3), (48, -60, .9)], 1.5, clip=B); b.ln([(-22, -220), (-28, -140, .1), (-36, -50, .3)], 1.4, clip=B)
    b.limb([(44, -304), (62, -252), (58, -204)], 27, bk, sleeve=None); b.ops.append(('line', A_([[b.x + 57 * b.k, b.y - 210 * b.k], [b.x + 64 * b.k, b.y]]), 6, 1., '#5f4034', None)); b.arm((-42, -306), 226, 28, '#c4b8a2', bk, .50, band=(.58, .78))
    P = []
    for i in range(30): a = i / 30 * 6.283; r = 1 + .13 * math.sin(i * 2.3 + b.g * .5); P.append((math.cos(a) * 58 * r, -326 + math.sin(a) * 24 * r, .18 * max(0, math.cos(a))))
    b.comp(P, bo, (), 1.5, 4); b.comp([(30, -330), (58, -316, .4), (70, -282, .9), (88, -250, 1.5), (112, -236, 2.0), (96, -228, 1.7), (70, -236, 1.2), (44, -266, .6), (24, -306)], bo, (4,), 1.5); P = []
    for i in range(46): a = i / 46 * 6.283; r = 1 + .050 * math.sin(i * 2.7) + .035 * math.sin(i * 4.9 + 1); P.append((math.cos(a) * 80 * r, -392 + math.sin(a) * 62 * r, .10 * max(0, math.cos(a) + .2)))
    H = b.comp(P, '#1f191c', (), 1.5, 3)
    for i in range(20): a = i * 2.4; rr = 14 + 56 * ((i * .618) % 1); cx, cy = math.cos(a) * rr, -392 + math.sin(a) * rr * .74; q = np.linspace(0, 4.6, 8); b.ln([(cx + math.cos(v + i) * 8, cy + math.sin(v + i) * 7.4) for v in q], 1.3, .6, '#4a3e40')
    b.comp([(-58, -440), (-42, -449), (-40, -496), (40, -500), (43, -449), (58, -441), (0, -432)], '#28232a', (0, 1, 2, 3, 4, 5), 1.6, 4); b.comp([(-42, -462), (0, -457), (43, -463), (43, -449), (0, -444), (-42, -449)], '#7f4234', (0, 2, 3, 5), 1.2, 4); b.comp([(-38, -496), (-45, -527), (-22, -511), (0, -534), (21, -512), (45, -528), (39, -499)], '#a0854a', (1, 2, 3, 4, 5), 1.4, 3)


def robin(b):
    d, sk, hr = '#4b4160', '#a67e5f', '#201b23'
    B = b.comp([(-11, -300), (-26, -294), (-45, -287), (-50, -268), (-37, -236), (-29, -206), (-40, -170), (-49, -112, .1), (-56, -52, .25), (-56, 0, .35), (-16, -8, .5), (24, 0, .7), (76, -6, 1.0), (122, -26, 1.5), (90, -90, .85), (56, -150, .3), (40, -180), (30, -206), (37, -236), (50, -268), (45, -287), (26, -294), (12, -300)], d, (9, 11, 13), 0); b.shade([(-70, 0), (-70, -290), (-16, -292), (-6, -240), (-10, -200), (-18, -110, .1), (-10, 0, .5)], B, .64)
